fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Assumes `a.len() == b.len()` and all chars are '0' or '1' as stated.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(ca, cb)| if ca == cb { '0' } else { '1' })
        .collect()
}

